sys_ux_data_broker_transform.script:
function transform(input) {
    // gs.info("=== Starting Discovery Success Rate Calculation (Last 30 Days) ===");
	var mostUsedClasses = input.classes ;
	var mostUsedClassesArray = mostUsedClasses.split(",") ;
	gs.print("mostUsedClasses" + mostUsedClasses )
    var results = []; // Array to store success rates as objects
    var ciCount = {}; // Store total CI count per class
    var successCount = {}; // Store successfully discovered CI count per class
    var ciName = {}; // Store successfully discovered CI count per class
    var totalRecords = 0;

    // Get the date 30 days ago
    var thirtyDaysAgo = new GlideDateTime();
    thirtyDaysAgo.addDaysUTC(-30);

    var gr = new GlideRecord('cmdb_ci');
    gr.addNotNullQuery('sys_class_name'); // Ensure valid CI classes are selected

    gr.query();

    // gs.info("Query executed: cmdb_ci records fetched.");

    while (gr.next() ) {
		if(mostUsedClassesArray.indexOf(gr.getValue('sys_class_name')) !== -1){
			// gs.print(mostUsedClassesArray.indexOf(gr.getValue('sys_class_name')));

        totalRecords++;
        var ciClass = gr.getValue('sys_class_name');
        var discoveryDate = gr.getValue('last_discovered');
		var displayName = gr.getDisplayValue('sys_class_name');
        // Initialize counters if not already set
		ciName[ciClass] = displayName
        if (!ciCount[ciClass]) {
            ciCount[ciClass] = 0;
            successCount[ciClass] = 0;
        }

        ciCount[ciClass]++; // Increment total CI count for the class

        if (discoveryDate && discoveryDate != '') {
            var discoverDateObj = new GlideDateTime(discoveryDate);

            // Check if discovery date is within the last 30 days
            if (discoverDateObj >= thirtyDaysAgo) {
                successCount[ciClass]++; // Increment successfully discovered CI count
            }
        }
		}
    }

    // gs.info("Total CIs processed: " + totalRecords);

    // Calculate success rate for each CI class (last 30 days)
    for (var ci in ciCount) {
        var total = ciCount[ci];
        var discovered = successCount[ci];
        var successRate = total > 0 ? (discovered / total) * 100 : 0;

        results.push({
			ci_name : ciName[ci] , 
            ci_class: ci,
            total_cis: total,
            discovered_last_30_days: discovered,
            success_rate:  successRate == 100 ? 100 + "%" :successRate.toFixed(1) + "%"
        });

        // gs.info("CI Class: " + ci +
        //         " | Total CIs: " + total +
        //         " | Discovered in Last 30 Days: " + discovered +
        //         " | Success Rate: " + successRate.toFixed(2) + "%");
    }

    // gs.info("=== Discovery Success Rate Calculation (Last 30 Days) Completed ===");
    gs.info("Final JSON Result: " + JSON.stringify(results));
	return results;

}
